function countPairs(deliciousness) {
  const MOD = 1000000007;
  const MAX_SUM = 1 << 21;
  const seen = new Map();
  let pairs = 0;
  for (const value of deliciousness) {
    for (let power = 1; power <= MAX_SUM; power *= 2) {
      const partner = power - value;
      if (seen.has(partner)) {
        pairs = (pairs + seen.get(partner)) % MOD;
      }
    }
    seen.set(value, (seen.get(value) || 0) + 1);
  }
  return pairs;
}

