function countPairs(deliciousness) {
  let total = 0;
  for (let i = 0; i < deliciousness.length; i++) {
    for (let j = i + 1; j < deliciousness.length; j++) {
      const sum = deliciousness[i] + deliciousness[j];
      if (sum > 0 && (sum & (sum - 1)) === 0) total++;
