function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const style = rand();
  const value = () => {
    if (style < 0.3) return int(0, 12);
    if (style < 0.6) {
      const power = 2 ** int(0, 20);
      return rand() < 0.5 ? power : Math.max(0, Math.min(1 << 20, 2 ** int(0, 21) - power));
    }
    if (style < 0.8) return int(0, 1 << 20);
    return rand() < 0.5 ? 1 : int(0, 3);
  };
  const n = size === 'large' ? int(1500, 2000) : int(1, 10);
  return [Array.from({ length: n }, value)];
}
